/*
 * A021399  Decimal expansion of 1/395.
 * https://oeis.org/A021399
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons
 * Formula:   a(n) is the (n+1)-th digit of the decimal expansion of 1/395
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* The decimal digits of 1/395 can be generated by long division:
       remainder r starts as 1; at each step r *= 10, 
       digit = r / 395, remainder r %= 395.  
       The n-th term a(n) corresponds to the (n+1)-th digit. */
    unsigned r = 1;          /* remainder after multiplying by 10 */
    seq_t  digit = 0;        /* current digit being produced */

    for (idx_t i = 0; i <= n; ++i) {
        r *= 10;
        digit = r / 395;
        r    %= 395;
        if (i == n) break;
    }
    return digit;
}
